        Array.AsReadOnly(observation ? ObservationVtableSlots : NavigationVtableSlots);

    internal static Snapshot Audit(byte[] bytes, bool observation)
    {
        int nt = Read32(bytes, 0x3c), optional = checked(nt + 24);
        if (Read16(bytes, 0) != 0x5a4d || Read32(bytes, nt) != 0x4550 || Read16(bytes, nt + 4) != 0x8664 ||
            Read16(bytes, optional) != 0x20b || Read16(bytes, nt + 20) != 240 ||
            Read16(bytes, nt + 22) != 8226 || Read32(bytes, optional + 16) != 23803324 ||
            Read32(bytes, optional + 32) != 4096 || Read32(bytes, optional + 36) != 512 ||
            Read32(bytes, optional + 60) != 1024 || Read16(bytes, optional + 68) != 2 ||
            Read16(bytes, optional + 70) != 352 ||
            Read16(bytes, nt + 6) != Sections.Length ||
            Read64(bytes, optional + 24) != 0x180000000 ||
            Read32(bytes, optional + 56) != 39284736 ||
            Read32(bytes, optional + 108) != Directories.Length)
            throw new InvalidDataException("feature_PE_layout_not_audited");
        int table = optional + 240;
        for (int i = 0; i < Sections.Length; i++)
        {
            int row = checked(table + i * 40);
            var expected = Sections[i];
            var name = System.Text.Encoding.ASCII.GetString(bytes, row, 8).TrimEnd('\0');
            if (name != expected.Name || Read32(bytes, row + 8) != expected.VirtualSize ||
                Read32(bytes, row + 12) != expected.Rva || Read32(bytes, row + 16) != expected.RawSize ||
                Read32(bytes, row + 20) != expected.Raw ||
                (uint)Read32(bytes, row + 36) != expected.Characteristics ||
                (long)expected.Raw + expected.RawSize > bytes.Length)
                throw new InvalidDataException("feature_section_layout_not_audited:" + expected.Name);
        }
        for (int i = 0; i < Directories.Length; i++)
            if (Read32(bytes, optional + 112 + i * 8) != Directories[i].Rva ||
                Read32(bytes, optional + 116 + i * 8) != Directories[i].Size)
                throw new InvalidDataException("feature_loader_directory_not_audited:" + i);

        var bodies = observation ? ObservationBodies : NavigationBodies;
        var code = new byte[bodies.Length][];
        for (int i = 0; i < bodies.Length; i++)
        {
            var body = bodies[i];
            var content = bytes.AsSpan(Offset(body.Rva, body.Length), body.Length);
            if (Convert.ToHexString(SHA256.HashData(content)) != body.Sha)
                throw new InvalidDataException($"feature_complete_body_mismatch:rva=0x{body.Rva:X}");
            code[i] = content.ToArray();
        }
        // Conservatively keep full static data/layout rather than claiming a
        // string/constant/vtable dependency map from a prologue alone.
        foreach (var section in Sections.Skip(1))
            if (Convert.ToHexString(SHA256.HashData(bytes.AsSpan(section.Raw, section.RawSize))) != section.Sha)
                throw new InvalidDataException("feature_static_section_mismatch:" + section.Name);

        // The file data baseline covers every table/constant. Runtime checks
        // cover the fixed Bot/MoveTo slots and float constants we directly use.
        // Import address slots and mutable globals are loader/engine-owned.
        var data = ProfileVtableSlots(observation).Select(rva => (rva, 8)).ToList();
        if (observation) data.Add((0x1782e0c, 4));
        var extraData = data.Select(range => new Data(range.Item1,
            bytes.AsSpan(Offset(range.Item1, range.Item2), range.Item2).ToArray())).ToArray();
        return new(bodies, code, extraData);
    }

    private static int Offset(int rva, int length)
    {
        var section = Sections.FirstOrDefault(s => rva >= s.Rva &&
            (long)rva + length <= (long)s.Rva + Math.Min(s.VirtualSize, s.RawSize));
        if (section.Name is null) throw new InvalidDataException("feature_RVA_outside_file");
        return checked(section.Raw + rva - section.Rva);
    }

    internal sealed record Data(int Rva, byte[] Bytes);
    internal sealed class Snapshot
    {
        private readonly Body[] _bodies;
        private readonly byte[][] _code;
        private readonly Data[] _data;
        internal Snapshot(Body[] bodies, byte[][] code, Data[] data)
        { _bodies = bodies; _code = code; _data = data; }

        internal bool TryBind(nint module, bool observation, out LoadedGuard? guard, out string reason)
        {
            guard = null;
            // Primary bodies are checked immediately by the adapters, including
            // the exact existing BotAI variants. Extra helpers are strict; an
            // unreviewed patch in any helper remains a reason to refuse a new
            // file profile even if that plugin also works on a reviewed file.
            var primary = observation
                ? new HashSet<int> { 0x2dda40, 0x2fc1d0, 0x2e6d30 }
                : new HashSet<int> { 0x2bafa0, 0x32a630, 0x32aaf0, 0x2de010, 0x2dd880,
                    0x330e90, 0x2cce50, 0x2cdc90, 0x2cb9a0 };
            var spans = _bodies.Select((body, i) => (body, i)).Where(row => !primary.Contains(row.body.Rva))
                .Select(row => new Data(row.body.Rva, _code[row.i])).ToList();
            foreach (var entry in _data)
            {
                var relocated = entry.Bytes.ToArray();
                if (entry.Rva != 0x1782e0c)
                    for (int i = 0; i < relocated.Length; i += 8)
                    {
                        long preferred = BinaryPrimitives.ReadInt64LittleEndian(relocated.AsSpan(i, 8));
                        if (preferred < 0x180000000 || preferred >= 0x180000000 + 39284736)
                        { reason = "feature_vtable_pointer_not_audited"; return false; }
                        BinaryPrimitives.WriteInt64LittleEndian(relocated.AsSpan(i, 8),
                            preferred - 0x180000000 + module.ToInt64());
                    }
                spans.Add(new(entry.Rva, relocated));
            }
            var candidate = new LoadedGuard(module, spans.ToArray());
            if (!candidate.Verify(out reason)) return false;
            guard = candidate;
            return true;
        }
    }

    internal sealed class LoadedGuard
    {
        private readonly nint _module;
        private readonly Data[] _spans;
        private readonly byte[][] _scratch;
        private long _lastCheck;
        private string? _failure;
        internal LoadedGuard(nint module, Data[] spans)
        {
            _module = module; _spans = spans;
            _scratch = spans.Select(span => new byte[span.Bytes.Length]).ToArray();
        }

        // No file reads, hashes or per-tick buffer allocations. Primary code
        // still has its immediate per-use checks. The bounded additional
        // dependencies are rechecked at most once a second and fail latched.
        internal bool VerifyIfDue(out string reason)
        {
            if (_failure is not null) { reason = _failure; return false; }
            if (Environment.TickCount64 - _lastCheck < 1000) { reason = ""; return true; }
            return Verify(out reason);
        }
        internal bool Verify(out string reason)
        {
            for (int i = 0; i < _spans.Length; i++)
            {
                var span = _spans[i];
                Marshal.Copy(_module + span.Rva, _scratch[i], 0, _scratch[i].Length);
                if (!_scratch[i].AsSpan().SequenceEqual(span.Bytes))
                {
                    reason = _failure = $"feature_loaded_dependency_mismatch:rva=0x{span.Rva:X}";
                    return false;
                }
            }
            _lastCheck = Environment.TickCount64; reason = ""; return true;
        }
    }

    private static int Read32(byte[] bytes, int offset) => BinaryPrimitives.ReadInt32LittleEndian(bytes.AsSpan(offset, 4));
    private static long Read64(byte[] bytes, int offset) => BinaryPrimitives.ReadInt64LittleEndian(bytes.AsSpan(offset, 8));
    private static ushort Read16(byte[] bytes, int offset) => BinaryPrimitives.ReadUInt16LittleEndian(bytes.AsSpan(offset, 2));
}
